<?php
/** 逐实例只读盘点；仅输出版本/文件指纹，不暴露凭据或业务摘要。 */
$site=$argv[1]??'';$sites=['rh'=>['rh.cc3798.com','ruihao','3306'],'008'=>['008.cc3798.com','mohe_008','3307'],'010'=>['010.cc3798.com','mohe_010_app','3307']];if(!isset($sites[$site]))throw new RuntimeException('INSTANCE_REQUIRED');
[$domain,$name,$port]=$sites[$site];$root='/www/wwwroot/'.$domain;$env=parse_ini_file($root.'/.env',true,INI_SCANNER_RAW);$cfg=array_change_key_case($env['DATABASE']??$env['database']??[]);if($cfg['database']!==$name||(string)$cfg['hostport']!==$port)throw new RuntimeException('INSTANCE_MISMATCH');
$files=['app/services/fund/StoreFundServices.php','app/services/other/export/ExportServices.php','mohe/services/SpreadsheetExcelService.php','app/controller/store/fund/StoreFund.php','app/controller/admin/v1/fund/StoreFund.php','route/store.php','route/admin.php','.env'];
$result=['site'=>$site,'root'=>$root,'database'=>$name,'port'=>$port,'files'=>[],'frontends'=>[]];foreach($files as $f)$result['files'][$f]=hash_file('sha256',$root.'/'.$f);
$roots=[$root];if($site==='rh')$roots[]=$root.'-8080';foreach($roots as $r)foreach(['public/view_cashier_v3/index.html','public/view_fund_v3/index.html','public/system.html']as $entry){if(!is_file($r.'/'.$entry))continue;$html=file_get_contents($r.'/'.$entry);$assets=[];preg_match_all('~(?:src|href)=["\']?([^"\'\s>]+\.(?:js|css))~',$html,$m);foreach($m[1] as $url){if(parse_url($url,PHP_URL_SCHEME))continue;$f=$r.'/public/'.ltrim(parse_url($url,PHP_URL_PATH),'/');if(is_file($f))$assets[$url]=hash_file('sha256',$f);}$result['frontends'][]=['root'=>$r,'entry'=>$entry,'sha256'=>hash('sha256',$html),'assets'=>$assets];}
$db=new PDO('mysql:host='.$cfg['hostname'].';port='.$port.';dbname='.$name.';charset=utf8mb4',$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('SET TRANSACTION READ ONLY');$db->beginTransaction();try{$result['upgrades']=$db->query('SELECT upgrade_key,code_version,executed_at FROM eb_database_upgrade_log ORDER BY id DESC LIMIT 8')->fetchAll(PDO::FETCH_ASSOC);}finally{$db->rollBack();}echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),PHP_EOL;
